import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    allowed_species = {'Adelie', 'Chinstrap', 'Gentoo'}
    df = df[df['species'].isin(allowed_species)]
    df = df[df['body_mass_g'] >= 0]
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].mean().to_dict()
